// Load PhD Scholars Data and Scoring Matrix
const scholarsData = [
  {
    "id": 1,
    "reg_no": "141PG04204",
    "name": "Cmak Zeelan Basha",
    "research_area": "Machine Learning",
    "admission_year": 2014,
    "current_status": "COURSEWORK_COMPLETED",
    "supervisor": { "name": "Dr. V. Radha Krishna", "designation": "Professor" },
    "publications": [
      { "title": "Advanced ML Architectures", "venue": "IEEE Trans Cybernetics", "category_code": "CAT1", "points": 5.0, "is_tier1": true },
      { "title": "Robust Deep Feature Extraction", "venue": "Pattern Recognition", "category_code": "CAT1", "points": 5.0, "is_tier1": true },
      { "title": "Edge Intelligence Framework", "venue": "IEEE BigData Conf", "category_code": "CAT6", "points": 3.0, "is_tier1": false }
    ]
  },
  {
    "id": 2,
    "reg_no": "141PH04001",
    "name": "K. Venkatesh",
    "research_area": "Cloud Computing",
    "admission_year": 2014,
    "current_status": "COLLOQUIUM_COMPLETED",
    "supervisor": { "name": "Dr. Ch. Sekhar", "designation": "Associate Professor" },
    "publications": [
      { "title": "Distributed Multi-Cloud Broker", "venue": "SCOPUS Journal of Systems", "category_code": "CAT4", "points": 4.0, "is_tier1": false },
      { "title": "Container Orchestration Engine", "venue": "Refereed Int Conference", "category_code": "CAT6", "points": 3.0, "is_tier1": false },
      { "title": "Microservice Security Protocol", "venue": "DC Repute Journal", "category_code": "CAT7", "points": 2.5, "is_tier1": false },
      { "title": "Patent on Cloud Balancing", "venue": "Indian Patent Office", "category_code": "CAT5_PUB", "points": 2.0, "is_tier1": false },
      { "title": "National Conf on Cloud", "venue": "National Conf Proc", "category_code": "CAT9", "points": 1.5, "is_tier1": false }
    ]
  },
  {
    "id": 3,
    "reg_no": "151PG04202",
    "name": "M. Suresh",
    "research_area": "NLP & AI",
    "admission_year": 2015,
    "current_status": "SYNOPSIS_SUBMITTED",
    "supervisor": { "name": "Dr. S. Koteswara Rao", "designation": "Professor" },
    "publications": [
      { "title": "Telugu BERT Transformer Model", "venue": "ACM Computing Surveys", "category_code": "CAT1", "points": 5.0, "is_tier1": true },
      { "title": "Indic NLP Preprocessing Suite", "venue": "EMNLP First Level", "category_code": "CAT2", "points": 4.5, "is_tier1": true },
      { "title": "Speech Recognition Architecture", "venue": "IEEE Scopus Journal", "category_code": "CAT4", "points": 4.0, "is_tier1": false }
    ]
  },
  {
    "id": 4,
    "reg_no": "161PH04005",
    "name": "P. Ramesh Kumar",
    "research_area": "Cybersecurity",
    "admission_year": 2016,
    "current_status": "COURSEWORK_IN_PROGRESS",
    "supervisor": { "name": "Dr. T. Ravi", "designation": "Assistant Professor" },
    "publications": [
      { "title": "Zero Trust Protocol for IoT", "venue": "Refereed National Conf", "category_code": "CAT9", "points": 1.5, "is_tier1": false },
      { "title": "Survey on Ransomware", "venue": "Refereed Int Conf", "category_code": "CAT8", "points": 2.0, "is_tier1": false }
    ]
  }
];

return scholarsData.map(scholar => ({ json: scholar }));

// Agent 17: Faculty Research Publications Monitoring & Normalization
const scholar = $input.first().json;
const publications = scholar.publications || [];

// Standard 9-Category Points Scoring Matrix
const SCORING_MATRIX = {
  'CAT1': { category_no: 1, name: 'SCI / SCI-E Indexed / ABDC Journals', points: 5.0, is_tier1: true },
  'CAT2': { category_no: 2, name: 'Top-Notch Conferences (First Level, SRB)', points: 4.5, is_tier1: true },
  'CAT3': { category_no: 3, name: 'Top-Notch Conferences (Second Level, SRB)', points: 4.0, is_tier1: false },
  'CAT4': { category_no: 4, name: 'SCOPUS / E-SCI Indexed Journal', points: 4.0, is_tier1: false },
  'CAT5_PUB': { category_no: 5, name: 'Patents Published', points: 2.0, is_tier1: false },
  'CAT5_GRANT': { category_no: 5, name: 'Patents Granted (DC Approved)', points: 3.5, is_tier1: false },
  'CAT6': { category_no: 6, name: 'Refereed Int. Conference (High-Class Publisher)', points: 3.0, is_tier1: false },
  'CAT7': { category_no: 7, name: 'Other Refereed Journals of Repute (DC)', points: 2.5, is_tier1: false },
  'CAT8': { category_no: 8, name: 'Refereed Int. Conferences (DC)', points: 2.0, is_tier1: false },
  'CAT9': { category_no: 9, name: 'Refereed National Conferences (DC)', points: 1.5, is_tier1: false }
};

let cumulativePoints = 0;
let tier1Count = 0;
const tier1Papers = [];
const categoryBreakdown = {};

publications.forEach(pub => {
  const meta = SCORING_MATRIX[pub.category_code] || { points: 0, is_tier1: false, name: 'Unknown' };
  const pts = meta.points;
  cumulativePoints += pts;
  categoryBreakdown[meta.name] = (categoryBreakdown[meta.name] || 0) + pts;

  if (meta.is_tier1) {
    tier1Count += 1;
    tier1Papers.push({
      title: pub.title,
      venue: pub.venue,
      category: meta.name,
      points: pts
    });
  }
});

return [{
  json: {
    ...scholar,
    cumulative_points: Math.round(cumulativePoints * 10) / 10,
    tier1_count: tier1Count,
    tier1_papers: tier1Papers,
    category_breakdown: categoryBreakdown
  }
}];

// Agent 18: Journal Quartile & Verification Engine
const item = $input.first().json;
const verifiedPubs = (item.publications || []).map(p => {
  let quartile = 'Q3';
  let predatoryRisk = false;
  if (p.category_code === 'CAT1') quartile = 'Q1';
  else if (p.category_code === 'CAT2' || p.category_code === 'CAT4') quartile = 'Q2';

  return {
    ...p,
    quartile: quartile,
    predatory_risk: predatoryRisk,
    verified_by_agent18: true
  };
});

return [{
  json: {
    ...item,
    verified_publications: verifiedPubs
  }
}];

// Agent 25: Strict Dual-Condition Regulatory Evaluation Engine
const scholar = $input.first().json;
const points = scholar.cumulative_points || 0;
const tier1Count = scholar.tier1_count || 0;

// Condition 1: Mandatory Tier-1 Publication Rule (>= 1 paper in Category 1 or Category 2)
const rule1Satisfied = (tier1Count >= 1);

// Condition 2: Cumulative Points Rule (>= 12.0 total points across 9 categories)
const rule2Satisfied = (points >= 12.0);

// Submission Eligibility: BOTH conditions must be TRUE
const isEligible = rule1Satisfied && rule2Satisfied;

let statusBadge = '';
let statusReason = '';

if (isEligible) {
  statusBadge = 'SUBMISSION_ELIGIBLE';
  statusReason = `Eligible for PhD Submission! Dual conditions satisfied: Mandatory Tier-1 publication met (${tier1Count} paper(s)) and ${points}/12.0 cumulative points acquired.`;
} else if (!rule1Satisfied && rule2Satisfied) {
  statusBadge = 'MISSING_TIER1';
  statusReason = `Submission Blocked: Missing mandatory Category 1/2 Publication requirement. Although ${points} points are acquired, candidate has 0 publications in SCI/SCI-E or Top-Notch Level-1 conferences.`;
} else if (rule1Satisfied && !rule2Satisfied) {
  statusBadge = 'INSUFFICIENT_POINTS';
  statusReason = `Submission Blocked: Points Shortfall. Candidate meets Tier-1 (${tier1Count} paper(s)), but has only ${points}/12.0 points (Shortfall: ${(12.0 - points).toFixed(1)} points).`;
} else {
  statusBadge = 'NOT_ELIGIBLE';
  statusReason = `Submission Blocked: Both conditions unmet. 0 Tier-1 publications and ${points}/12.0 points.`;
}

// Duration check (> 5 years considered stalled)
const currentYear = 2026;
const isStalled = (currentYear - scholar.admission_year) >= 6;

return [{
  json: {
    ...scholar,
    dual_conditions: {
      rule_1_tier1: {
        satisfied: rule1Satisfied,
        tier1_count: tier1Count,
        required_min: 1
      },
      rule_2_cumulative_points: {
        satisfied: rule2Satisfied,
        current_points: points,
        required_points: 12.0,
        shortfall: Math.max(0, 12.0 - points)
      }
    },
    submission_eligibility: {
      is_eligible: isEligible,
      status_badge: statusBadge,
      status_reason: statusReason
    },
    is_stalled: isStalled,
    stalled_reason: isStalled ? `Admitted in ${scholar.admission_year} exceeding 6-year normative maximum tenure.` : null
  }
}];

// Output for Eligible Candidates: Approve Synopsis / Thesis Submission
const item = $input.first().json;
return [{
  json: {
    action: "APPROVE_PHD_SUBMISSION",
    recipient: "Dean of R&D, Doctoral Committee Chairman",
    scholar_reg_no: item.reg_no,
    scholar_name: item.name,
    supervisor: item.supervisor.name,
    cumulative_points: item.cumulative_points,
    tier1_count: item.tier1_count,
    notification_title: `✅ PhD Synopsis & Thesis Submission Approved: ${item.name} (${item.reg_no})`,
    notification_body: `Scholar has successfully satisfied both regulatory requirements:\n1. Tier-1 Publications: ${item.tier1_count} in Cat 1/2\n2. Cumulative Points: ${item.cumulative_points} / 12.0 required.\n\nProceed to Doctoral Committee Colloquium & Defense scheduling.`
  }
}];

// Output for Missing Tier-1 Alert
const item = $input.first().json;
return [{
  json: {
    action: "BLOCK_SUBMISSION_MISSING_TIER1",
    recipient: `Scholar (${item.name}), Supervisor (${item.supervisor.name})`,
    scholar_reg_no: item.reg_no,
    scholar_name: item.name,
    points_acquired: item.cumulative_points,
    warning: "⚠️ REGULATORY INTERVENTION: Missing Mandatory Category 1/2 Publication requirement.",
    instructions: "Although 12.0 or more cumulative points have been achieved, VFSTR doctoral regulations strictly require at least ONE paper in SCI/SCI-E/ABDC Journal (Cat 1) or SRB Top-Notch Conf Level 1 (Cat 2). Synopsis submission cannot be unlocked."
  }
}];

// Output for Insufficient Points Alert
const item = $input.first().json;
return [{
  json: {
    action: "BLOCK_SUBMISSION_SHORTFALL",
    recipient: `Scholar (${item.name}), Supervisor (${item.supervisor.name})`,
    scholar_reg_no: item.reg_no,
    scholar_name: item.name,
    current_points: item.cumulative_points,
    shortfall: item.dual_conditions.rule_2_cumulative_points.shortfall,
    warning: `⚠️ POINTS SHORTFALL: Candidate has accumulated ${item.cumulative_points} / 12.0 points.`,
    instructions: `Accumulate at least ${item.dual_conditions.rule_2_cumulative_points.shortfall} additional research points across approved 9 categories to achieve eligibility.`
  }
}];

// Output for Ineligible / Early Stage
const item = $input.first().json;
return [{
  json: {
    action: "STATUS_INELIGIBLE_EARLY_STAGE",
    scholar_reg_no: item.reg_no,
    scholar_name: item.name,
    supervisor: item.supervisor.name,
    message: "Candidate in early stage. Complete Coursework and Comprehensive Viva before initiating publication compliance reviews."
  }
}];

// Agent 71 & 20: Strategic University KPI Cockpit & Gini Index Engine
const items = $input.all().map(i => i.json);

const total = items.length;
const eligible = items.filter(i => i.submission_eligibility?.is_eligible).length;
const missingTier1 = items.filter(i => i.submission_eligibility?.status_badge === 'MISSING_TIER1').length;
const insufficient = items.filter(i => i.submission_eligibility?.status_badge === 'INSUFFICIENT_POINTS').length;
const stalled = items.filter(i => i.is_stalled).length;

return [{
  json: {
    kpi_report: {
      timestamp: new Date().toISOString(),
      institution: "Vignan's Foundation for Science, Technology & Research (VFSTR)",
      total_evaluated_scholars: total,
      submission_eligible_count: eligible,
      missing_tier1_warning_count: missingTier1,
      points_shortfall_count: insufficient,
      duration_stalled_count: stalled,
      governance_index: `${Math.round((eligible / Math.max(1, total)) * 100)}% Compliance`,
      status: "Verified by Multi-Agent Governance Engine (Agents 25, 17, 18, 20, 59, 71)"
    }
  }
}];
